import{_ as t,o,c as a,ag as d}from"./chunks/framework.CPvOxTBX.js";const y=JSON.parse('{"title":"Dictionary Links","description":"","frontmatter":{},"headers":[],"relativePath":"guide/dictionary-links.md","filePath":"guide/dictionary-links.md","lastUpdated":1793438909000}'),r={name:"guide/dictionary-links.md"};function n(i,e,c,s,h,l){return o(),a("div",null,e[0]||(e[0]=[d('<h1 id="dictionary-links" tabindex="-1">Dictionary Links <a class="header-anchor" href="#dictionary-links" aria-label="Permalink to &quot;Dictionary Links&quot;">​</a></h1><p>Ciyue follows the link conventions that MDict and GoldenDict dictionaries already use. This page lists the accepted shapes and the one escape Ciyue adds on top of them.</p><h2 id="entry-links" tabindex="-1">Entry links <a class="header-anchor" href="#entry-links" aria-label="Permalink to &quot;Entry links&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Link</th><th>Where it goes</th></tr></thead><tbody><tr><td><code>entry://word</code></td><td>The entry <code>word</code></td></tr><tr><td><code>bword://word</code></td><td>Same as <code>entry://word</code> (Babylon spelling)</td></tr><tr><td><code>entry://word#anchor</code></td><td>The entry <code>word</code>, scrolled to <code>anchor</code></td></tr><tr><td><code>entry://#anchor</code></td><td>The entry already on screen, scrolled to <code>anchor</code></td></tr><tr><td><code>entry://word##anchor</code></td><td>The entry literally named <code>word#anchor</code></td></tr></tbody></table><p><code>bword://</code> behaves exactly like <code>entry://</code>, so every form above has a <code>bword://</code> twin.</p><h2 id="headwords-that-contain" tabindex="-1">Headwords that contain <code>#</code> <a class="header-anchor" href="#headwords-that-contain" aria-label="Permalink to &quot;Headwords that contain `#`&quot;">​</a></h2><p>A single <code>#</code> always separates the headword from an anchor. A headword that itself contains <code>#</code> therefore has to escape it by doubling:</p><table tabindex="0"><thead><tr><th>Headword</th><th>Write</th></tr></thead><tbody><tr><td><code>tag#sumeru</code></td><td><code>entry://tag##sumeru</code></td></tr></tbody></table><p>Escaping and separation combine, so <code>entry://tag##sumeru#x</code> opens the entry <code>tag#sumeru</code> and scrolls to <code>x</code>, while <code>entry://tag###sumeru</code> opens the entry <code>tag#</code> and scrolls to <code>sumeru</code>.</p><p>This escaping is specific to Ciyue. GoldenDict-ng splits at a <code>#</code> as well, but offers no way to reach a headword that contains one.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Anchors scroll, they are not part of the browsing history: going back never re-triggers a scroll.</li><li>A link with no headword scrolls the entry on screen and does not look anything up.</li><li>The anchor target is matched against both <code>id</code> and <code>name</code> attributes, so anchors written for either style work.</li><li>An anchor belongs to the entry of the dictionary that contains the link. A sibling dictionary in the same group that happens to have the same headword does not get scrolled instead.</li></ul><h2 id="audio-and-video" tabindex="-1">Audio and video <a class="header-anchor" href="#audio-and-video" aria-label="Permalink to &quot;Audio and video&quot;">​</a></h2><p>Audio references keep the MDict spelling <code>&lt;a href=&quot;sound://file.mp3&quot;&gt;…&lt;/a&gt;</code> and are played from the dictionary&#39;s <code>.mdd</code>, or from a StarDict <code>res/</code> resource.</p><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to &quot;Background&quot;">​</a></h2><p>For the reasoning behind these rules — how GoldenDict-ng, MDict and Babylon treat each scheme, why <code>gdlookup://localhost</code> exists, and where Ciyue goes further — see <a href="./dictionary-link-schemes.html">Dictionary Link Schemes: A Deep Dive</a>.</p>',16)]))}const p=t(r,[["render",n]]);export{y as __pageData,p as default};
